window.kbPageData["views/entry/k-03aa482b6a61fec7"] = {"key":"entry/k-03aa482b6a61fec7","state":{"route":"entry/k-03aa482b6a61fec7"},"node":{"id":"k-03aa482b6a61fec7","mode":"k","title":"增长贡献率","type":"概念与词义","domain":"统计","reading":"","intro":"","priority":100,"aliases":["增长贡献率等于部分贡献增量除以总体增量","增长贡献率等于部分增长量除以整体增长量","增长贡献率＝部分增长量÷整体增长量×100%","增长贡献率等于部分增量除以总体增量"],"qs":["国考 2024 副省级 行测#119","国考 2024 行政执法 行测#119","江苏 2025 B类 行测#122","江苏 2025 C类 行测#117"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":4,"repeatPositions":0,"directorySummary":"增长贡献率是某一部分对总体增量的贡献所占的比重。总体增量不为零时，用该部分贡献的增量除以总体增量，通常以百分比表示。","review":{"definition":"增长贡献率是某一部分对总体增量的贡献所占的比重。总体增量不为零时，用该部分贡献的增量除以总体增量，通常以百分比表示。","explanation":"第119题按新增粮食生产能力得到充分利用的假设，将中部六省中型灌区的新增粮食生产能力合计作为分子。六省合计36921.7万公斤，折合36.9217万吨。以全国粮食同比增产量368万吨为分母，算得约10.03%，对应B项“超过9%”。","references":[],"evidence":"如全国中型灌区新增粮食生产能力均得到充分利用","disposition":"独立词条","basis":"据原题和解析编释。","title":"增长贡献率","related":[],"examFocus":{"国考 2024 副省级 行测#119":"用增长贡献率比较中部六省中型灌区的新增粮食生产能力合计与全国粮食同比增产量，注意统一质量单位。","国考 2024 行政执法 行测#119":"在新增产能充分利用的假设下，统一单位后比较中部六省中型灌区新增粮食生产能力合计与全国粮食同比增产量。","江苏 2025 B类 行测#122":"根据现期量和同比增速求增长量，再比较东北片区与全市同期接待过夜游客人次的增量。","江苏 2025 C类 行测#117":"计算增长贡献率时，比较东北片区与全市接待过夜游客人次的同比增量。"}},"readings":[{"origin":"k-03aa482b6a61fec7","title":"增长贡献率","qs":["国考 2024 行政执法 行测#119"],"definition":"增长贡献率是某一部分对总体增量的贡献所占的比重。总体增量不为零时，用该部分贡献的增量除以总体增量，通常以百分比表示。","explanation":"第119题按新增粮食生产能力得到充分利用的假设，将中部六省中型灌区的新增粮食生产能力合计作为分子。六省合计36921.7万公斤，折合36.9217万吨。以全国粮食同比增产量368万吨为分母，算得约10.03%，对应B项“超过9%”。","evidence":"如全国中型灌区新增粮食生产能力均得到充分利用","doubt":"","references":[]},{"origin":"k-121a4ddb2e873bf3","title":"增长贡献率","qs":["江苏 2025 B类 行测#122"],"definition":"增长贡献率表示某一部分的增长量占整体增长量的百分比。整体增长量非零时，用同一比较期内的部分增长量除以整体增长量，再乘以100%。","explanation":"第122题以东北片区2023年比上年增加的过夜游客人次为分子，以全市同期增加的过夜游客人次为分母。按“增长量＝现期量×增长率÷（1＋增长率）”，用东北片区的1125万人次和38.2%求得增量为1125×0.382÷1.382，用全市的10190万人次和88.1%求得增量为10190×0.881÷1.881。两项增量相除约为6.52%，对应选项A。","evidence":"对全市接待过夜游客增长的贡献率","doubt":"","references":[]},{"origin":"k-5670e891c3562e27","title":"增长贡献率","qs":["江苏 2025 C类 行测#117"],"definition":"增长贡献率表示某一部分的增长量占同期整体增长量的百分比。整体增长量非零时，增长贡献率＝部分增长量÷整体增长量×100%。","explanation":"本题的分子是东北片区过夜游客人次的同比增长量，分母是全市过夜游客人次的同比增长量。用“现期量×同比增长率÷（1＋同比增长率）”分别求得两者为1125×0.382÷1.382和10190×0.881÷1.881，单位均为万人次。两者相除后化为百分数，约为6.5%，对应A项。","evidence":"增长对全市接待过夜游客增长的贡献率","doubt":"","references":[]},{"origin":"k-a9cdb3a2b85d2d02","title":"增长贡献率","qs":["国考 2024 副省级 行测#119"],"definition":"增长贡献率表示某一组成部分的增量占同期总体增量的比重。总体增量为正时，用部分增量除以总体增量，并以百分比表示。","explanation":"在题设新增粮食生产能力均得到充分利用的条件下，将中部六省中型灌区的新增粮食生产能力计作对全国粮食增产的贡献。六省合计为36921.7万公斤，折合36.9217万吨。以全国粮食产量同比增加的368万吨为分母，算得贡献占比约为10.03%，超过9%，对应B项。","evidence":"中部六省中型灌区新增粮食生产能力对全国粮食增产的贡献占比","doubt":"","references":[]}]},"questions":{"国考 2024 副省级 行测#119":{"paper":"国考 2024 副省级 行测","n":119,"mod":"资料分析","src":["a566fec37e508ca7f975.pdf",24],"asrc":["a475ecf57d968bc14cd6.pdf",38],"card":"098b2b13a95b2f7c40b4d1aa","links":[{"id":"k-03aa482b6a61fec7","role":"解题依据","why":"在充分利用的设定下，以中部六省新增产能作为贡献量，以全国粮食增产量作为总体增量。"}]},"国考 2024 行政执法 行测#119":{"paper":"国考 2024 行政执法 行测","n":119,"mod":"资料分析","src":["dfddc59dc6e7d9da5d71.pdf",25],"asrc":["6493f3a6a55c38431852.pdf",39],"card":"9a26f46ddffc5110d57eaef4","links":[{"id":"k-03aa482b6a61fec7","role":"解题依据","why":"按题设将六省新增粮食生产能力视作贡献增量，以全国粮食增产量为总体增量。"}]},"江苏 2025 B类 行测#122":{"paper":"江苏 2025 B类 行测","n":122,"mod":"资料分析","src":["91e0d9fd02ca7ec6d61f.pdf",25],"asrc":["f2ff67a0f2a2f7e8e926.pdf",41],"card":"66462b9a39d72fc65a18752b","links":[{"id":"k-03aa482b6a61fec7","role":"直接考查","why":"题目要求确定贡献率的分子为片区增量、分母为全市增量。"}]},"江苏 2025 C类 行测#117":{"paper":"江苏 2025 C类 行测","n":117,"mod":"资料分析","src":["ffc394a1c160f331ec57.pdf",24],"asrc":["d1de3b437151c05b769e.pdf",36],"card":"90936bacc21651bc226bc33a","links":[{"id":"k-03aa482b6a61fec7","role":"直接考查","why":"贡献率的分子和分母分别是东北片区和全市的同比增长量。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-03aa482b6a61fec7":[["国考 2024 副省级 行测#119"],["国考 2024 行政执法 行测#119"],["江苏 2025 B类 行测#122"],["江苏 2025 C类 行测#117"]]}};
